query:
-- Delete all call records and their associated data
DELETE FROM callTranscripts WHERE callId IN (SELECT id FROM calls);
DELETE FROM calls;

-- Delete all tickets and their replies
DELETE FROM ticketReplies WHERE ticketId IN (SELECT id FROM tickets);
DELETE FROM tickets;

-- Verify deletion
SELECT 
  (SELECT COUNT(*) FROM calls) as remaining_calls,
  (SELECT COUNT(*) FROM tickets) as remaining_tickets,
  (SELECT COUNT(*) FROM callTranscripts) as remaining_transcripts,
  (SELECT COUNT(*) FROM ticketReplies) as remaining_replies;

